"use client";

// AI content planner, based on the AI Management screen in the Marketing Intelligence
// Hub Figma Make app: calendar → three questions → review AI drafts → add to calendar.
// Plans are generated by Gemini; the calendar is stored in this browser.

import Link from "next/link";
import { useState, useTransition } from "react";
import Icon from "@/components/ui/Icon";
import { Eyebrow, PageTitle, Panel } from "@/components/ui/Dashboard";
import { CopyButton } from "@/components/content-creation/ui";
import { createPostingPlan } from "@/app/(dashboard)/ai-management/actions";
import { CHANNEL_CODES, addDays, byDateTime, fromISODate, toISODate, upcoming, useCalendar, useToday } from "@/lib/calendar";
import { saveContentTrend } from "@/lib/contentTrend";
import useStored from "@/lib/useStored";
import { useBusiness } from "@/lib/settings";

const CHANNELS = Object.keys(CHANNEL_CODES);
const FREQUENCIES = [2, 3, 4, 5];
const WEEKDAYS = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const NOTE_KEY = "trendtracker:plan-note";
const NO_NOTE = "";

const BADGE = {
  IG: "bg-[#ffd7e6] text-[#8a1d4a]",
  TT: "bg-sense-navy text-paper",
  YT: "bg-[#ffd6d0] text-[#8b1f12]",
};

const primary =
  "inline-flex min-h-[42px] cursor-pointer items-center justify-center gap-2 rounded-[22px] bg-sense-lime px-[18px] text-[10px] font-extrabold uppercase text-sense-navy shadow-[0_5px_0_rgba(0,31,62,0.17)] transition hover:translate-y-0.5 hover:shadow-[0_3px_0_rgba(0,31,62,0.2)] disabled:cursor-wait disabled:opacity-60";
const outline =
  "inline-flex min-h-[38px] cursor-pointer items-center justify-center gap-1.5 rounded-[20px] border border-sense-blue/25 px-4 text-[11px] font-bold text-sense-blue transition hover:bg-sense-blue/10";

const fmtDay = (iso) =>
  fromISODate(iso).toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" });

function Badge({ channel }) {
  const code = CHANNEL_CODES[channel] ?? channel.slice(0, 2).toUpperCase();
  return (
    <span className={`inline-grid h-[18px] min-w-[22px] place-items-center rounded-md px-1 text-[9px] font-extrabold ${BADGE[code] ?? "bg-[#e2eadf]"}`}>
      {code}
    </span>
  );
}

function BackButton({ onClick, children }) {
  return (
    <button
      type="button"
      onClick={onClick}
      className="mb-4 inline-flex cursor-pointer items-center gap-1.5 text-[11px] font-bold text-paper/90 transition-colors hover:text-sense-lime"
    >
      <Icon name="chevron" size={16} className="rotate-180" /> {children}
    </button>
  );
}

function Step({ n }) {
  return (
    <span className="mb-2 inline-block rounded-full bg-paper/15 px-3 py-1 text-[10px] font-bold text-paper">
      Step {n} of 2
    </span>
  );
}

/* ---------- Step 1: three questions ---------- */

// Defined outside PlanForm so the textarea keeps focus while typing.
function Question({ n, title, hint, children }) {
  return (
    <div className="grid gap-3 border-b border-sense-blue/10 pb-5 last:border-0 last:pb-0 sm:grid-cols-[32px_minmax(0,1fr)]">
      <span className="grid size-8 place-items-center rounded-[10px] bg-sense-lime text-xs font-extrabold">{n}</span>
      <div className="grid gap-3">
        <div>
          <strong className="text-sm text-sense-blue">{title}</strong>
          <p className="text-[11px] text-[#5f706e]">{hint}</p>
        </div>
        {children}
      </div>
    </div>
  );
}

function PlanForm({ form, setForm, onSubmit, pending, error, onBack }) {
  const toggle = (c) =>
    setForm((f) => ({ ...f, channels: f.channels.includes(c) ? f.channels.filter((x) => x !== c) : [...f.channels, c] }));
  return (
    <div className="w-full">
      <BackButton onClick={onBack}>Back to calendar</BackButton>
      <Step n={1} />
      <PageTitle title="Create a content plan" description="Answer three quick questions. Sense AI will handle the timing and content mix." />

      <div className="grid gap-[18px] lg:grid-cols-[minmax(0,1fr)_320px]">
        <Panel className="grid gap-5">
          <Question n={1} title="What should your content achieve?" hint="A short sentence is enough.">
            <textarea
              aria-label="Content goal"
              value={form.goal}
              rows={3}
              maxLength={500}
              onChange={(e) => setForm((f) => ({ ...f, goal: e.target.value }))}
              placeholder="e.g. Build awareness of our new product line and drive visits to our website."
              className="w-full resize-y rounded-xl border border-sense-blue/15 bg-white/80 p-3 text-sm outline-none focus:ring-2 focus:ring-sense-blue/30"
            />
          </Question>
          <Question n={2} title="Where do you want to post?" hint="Choose one or more channels.">
            <div className="flex flex-wrap gap-2">
              {CHANNELS.map((c) => {
                const on = form.channels.includes(c);
                return (
                  <button
                    key={c}
                    type="button"
                    aria-pressed={on}
                    onClick={() => toggle(c)}
                    className={`inline-flex min-h-10 cursor-pointer items-center gap-2 rounded-xl border px-3 text-xs font-semibold transition ${
                      on ? "border-sense-blue bg-sense-blue text-paper" : "border-sense-blue/20 bg-white/70 text-sense-blue hover:bg-sense-blue/10"
                    }`}
                  >
                    <Badge channel={c} /> {c} {on && <b>✓</b>}
                  </button>
                );
              })}
            </div>
          </Question>
          <Question n={3} title="How often should you post?" hint="Sense AI will choose the best days and times.">
            <select
              aria-label="Posting frequency"
              value={form.perWeek}
              onChange={(e) => setForm((f) => ({ ...f, perWeek: Number(e.target.value) }))}
              className="w-full max-w-xs cursor-pointer rounded-xl border border-sense-blue/15 bg-white/80 p-3 text-sm outline-none focus:ring-2 focus:ring-sense-blue/30"
            >
              {FREQUENCIES.map((n) => (
                <option key={n} value={n}>
                  {n} posts per week
                </option>
              ))}
            </select>
          </Question>
        </Panel>

        <Panel as="aside" className="flex flex-col gap-3 self-start">
          <span className="grid size-10 place-items-center rounded-xl bg-sense-lime">
            <Icon name="sparkles" size={20} />
          </span>
          <h2 className="text-base font-bold text-sense-blue">That&apos;s all Sense AI needs</h2>
          <p className="text-xs leading-[1.55] text-[#5f706e]">
            It will draft {form.perWeek * 2} posts for the next two weeks and pick a time for each one.
          </p>
          <ul className="grid gap-2 text-[11px] text-sense-blue">
            <li className="flex items-center gap-2"><Icon name="content" size={14} /> {form.perWeek * 2} ready-to-review drafts</li>
            <li className="flex items-center gap-2"><Icon name="calendar" size={14} /> Dates and times selected</li>
            <li className="flex items-center gap-2"><Icon name="message" size={14} /> A caption for every post</li>
          </ul>
          <button type="button" onClick={onSubmit} disabled={pending} className={`${primary} mt-2`}>
            <Icon name="sparkles" size={14} /> {pending ? "Creating your plan…" : "Create my plan"}
          </button>
          {error && <p role="alert" className="text-[11px] font-semibold text-[#b84f4f]">{error}</p>}
        </Panel>
      </div>
    </div>
  );
}

/* ---------- Step 2: review ---------- */

function Review({ plan, form, selected, setSelected, onBack, onAdd }) {
  const all = selected.length === plan.posts.length;
  const toggle = (i) => setSelected((s) => (s.includes(i) ? s.filter((x) => x !== i) : [...s, i]));

  return (
    <div className="w-full">
      <BackButton onClick={onBack}>Edit answers</BackButton>
      <Step n={2} />
      <PageTitle title="Review your plan" description="Keep the posts you like. You can remove any post from the calendar later." />

      <Panel className="mb-[18px] flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex items-start gap-3">
          <Icon name="sparkles" size={18} className="mt-0.5 shrink-0 text-sense-blue" />
          <p className="grid gap-1 text-[11px] leading-[1.5] text-[#5f706e]">
            <strong className="text-xs text-sense-blue">
              {form.perWeek} posts per week across {form.channels.length} channel{form.channels.length > 1 ? "s" : ""}
            </strong>
            {plan.recommendation || `Plan focus: ${form.goal}`}
          </p>
        </div>
        <button type="button" onClick={() => setSelected(all ? [] : plan.posts.map((_, i) => i))} className={outline}>
          {all ? "Clear all" : "Select all"}
        </button>
      </Panel>

      <ul className="grid gap-3 md:grid-cols-2">
        {plan.posts.map((post, i) => {
          const on = selected.includes(i);
          return (
            <li key={post.title}>
              <button
                type="button"
                aria-pressed={on}
                onClick={() => toggle(i)}
                className={`grid w-full cursor-pointer grid-cols-[24px_minmax(0,1fr)_auto] items-start gap-3 rounded-[18px] border bg-paper/95 p-4 text-left text-sense-navy shadow-[0_5px_0_rgba(0,31,62,0.14)] transition hover:-translate-y-0.5 ${
                  on ? "border-sense-lime outline-2 -outline-offset-2 outline-sense-lime" : "border-paper/60 opacity-70"
                }`}
              >
                <span className={`grid size-6 place-items-center rounded-lg text-xs font-bold ${on ? "bg-sense-lime" : "bg-[#dce5d1]"}`}>
                  {on ? "✓" : ""}
                </span>
                <span className="grid min-w-0 gap-1">
                  <strong className="text-[13px] text-sense-blue">{post.title}</strong>
                  <small className="flex items-center gap-1.5 text-[10px] text-[#5f706e]">
                    <Badge channel={post.channel} /> {post.channel} · {post.format}
                  </small>
                  <span className="text-[11px] leading-[1.5] text-[#536669]">{post.caption}</span>
                </span>
                <time className="grid text-right text-[11px] font-semibold text-sense-blue">
                  {fmtDay(post.date)}
                  <small className="font-normal text-[#5f706e]">{post.time}</small>
                </time>
              </button>
            </li>
          );
        })}
      </ul>

      <footer className="mt-[18px] flex flex-col gap-3 rounded-[18px] bg-paper/15 p-4 text-paper sm:flex-row sm:items-center sm:justify-between">
        <p className="text-xs">
          <strong>{selected.length} posts selected</strong> · Nothing is published automatically.
        </p>
        <div className="flex gap-2">
          <button type="button" onClick={onBack} className="min-h-[42px] cursor-pointer rounded-[22px] border border-paper/40 px-4 text-[11px] font-bold transition hover:bg-paper/15">
            Back
          </button>
          <button type="button" onClick={onAdd} disabled={!selected.length} className={`${primary} disabled:cursor-not-allowed`}>
            Add to calendar <Icon name="calendar" size={14} />
          </button>
        </div>
      </footer>
    </div>
  );
}

/* ---------- Calendar ---------- */

function MonthCalendar({ posts, month, today: todayDate, onSelect, selectedId }) {
  const first = new Date(month.getFullYear(), month.getMonth(), 1);
  const start = addDays(first, -first.getDay());
  const weeks = Math.ceil((first.getDay() + new Date(month.getFullYear(), month.getMonth() + 1, 0).getDate()) / 7);
  const today = toISODate(todayDate);
  const byDay = {};
  for (const p of posts) (byDay[p.date] ??= []).push(p);

  return (
    <div className="hidden sm:block">
      <div className="grid grid-cols-7 pb-2 text-center text-[10px] font-bold text-[#5f706e]">
        {WEEKDAYS.map((d) => (
          <span key={d}>{d.slice(0, 3)}</span>
        ))}
      </div>
      <div className="grid grid-cols-7 gap-1.5">
        {Array.from({ length: weeks * 7 }, (_, i) => {
          const day = addDays(start, i);
          const iso = toISODate(day);
          const inMonth = day.getMonth() === month.getMonth();
          const items = (byDay[iso] ?? []).sort(byDateTime);
          return (
            <div
              key={iso}
              className={`flex min-h-[92px] min-w-0 flex-col gap-1 rounded-xl border p-1.5 ${
                inMonth ? "border-sense-blue/10 bg-white/70" : "border-transparent bg-white/25 text-[#9aa6a6]"
              }`}
            >
              <span
                className={`grid size-6 place-items-center rounded-full text-[11px] font-semibold ${
                  iso === today ? "bg-sense-blue text-paper" : ""
                }`}
              >
                {day.getDate()}
              </span>
              {items.map((p) => (
                <button
                  key={p.id}
                  type="button"
                  onClick={() => onSelect(p.id)}
                  className={`grid cursor-pointer gap-0.5 rounded-lg p-1.5 text-left transition ${
                    selectedId === p.id ? "bg-sense-lime" : "bg-[#e9f0d8] hover:bg-sense-lime/70"
                  }`}
                >
                  <small className="flex items-center gap-1 text-[9px] text-[#5f706e]">
                    <Badge channel={p.channel} /> {p.time}
                  </small>
                  <strong className="line-clamp-2 text-[10px] leading-tight text-sense-navy">{p.title}</strong>
                </button>
              ))}
            </div>
          );
        })}
      </div>
    </div>
  );
}

/** Small screens get a list instead of a 7-column grid. */
function AgendaList({ posts, onSelect, selectedId }) {
  if (!posts.length) return <p className="py-6 text-center text-xs text-[#5f706e] sm:hidden">No posts this month.</p>;
  return (
    <ul className="grid gap-2 sm:hidden">
      {posts.map((p) => (
        <li key={p.id}>
          <button
            type="button"
            onClick={() => onSelect(p.id)}
            className={`flex w-full cursor-pointer items-center gap-3 rounded-xl p-3 text-left ${selectedId === p.id ? "bg-sense-lime" : "bg-white/70"}`}
          >
            <Badge channel={p.channel} />
            <span className="min-w-0 flex-1">
              <strong className="block truncate text-xs">{p.title}</strong>
              <small className="text-[10px] text-[#5f706e]">{fmtDay(p.date)} · {p.time}</small>
            </span>
          </button>
        </li>
      ))}
    </ul>
  );
}

function PostDetail({ post, onClose, onRemove }) {
  const creator = ["Video", "Reel", "Short"].includes(post.format) ? "video" : "social";
  return (
    <Panel className="mt-[18px]">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="min-w-0">
          <Eyebrow>{fmtDay(post.date)} · {post.time}</Eyebrow>
          <h3 className="text-base font-bold text-sense-blue">{post.title}</h3>
          <p className="mt-1 flex items-center gap-1.5 text-[11px] text-[#5f706e]">
            <Badge channel={post.channel} /> {post.channel} · {post.format}
          </p>
        </div>
        <button type="button" onClick={onClose} aria-label="Close post details" className="cursor-pointer rounded-full p-1 text-lg leading-none text-sense-blue hover:bg-sense-blue/10">
          ×
        </button>
      </div>
      {post.caption && (
        <div className="mt-3 flex items-start gap-2 rounded-xl bg-white/70 p-3">
          <p className="flex-1 text-xs leading-[1.6] text-[#344c53]">{post.caption}</p>
          <CopyButton text={post.caption} />
        </div>
      )}
      <div className="mt-4 flex flex-wrap gap-2">
        <Link
          href={`/content-creation/${creator}`}
          onClick={() =>
            saveContentTrend(
              { name: post.title, audience: "", platform: post.channel, format: post.format, hook: post.caption },
              { source: "calendar", path: `/content-creation/${creator}` },
            )
          }
          className={primary}
        >
          <Icon name="edit" size={14} /> Write this post
        </Link>
        <button type="button" onClick={onRemove} className={`${outline} hover:border-[#b84f4f] hover:bg-[#ff7f7f]/15 hover:text-[#b84f4f]`}>
          Remove from calendar
        </button>
      </div>
    </Panel>
  );
}

function StatusCard({ icon, label, value, note }) {
  return (
    <Panel className="grid gap-1.5">
      <span className="flex items-center gap-1.5 text-[11px] font-bold text-[#5f706e]">
        <Icon name={icon} size={16} /> {label}
      </span>
      <strong className="text-base text-sense-blue">{value}</strong>
      <small className="text-[11px] text-[#5f706e]">{note}</small>
    </Panel>
  );
}

function Dashboard({ onCreate, added, onDismiss }) {
  const { posts, removePost } = useCalendar();
  const [note] = useStored(NOTE_KEY, NO_NOTE);
  const [channel, setChannel] = useState("All");
  const today = useToday();
  const [monthOffset, setMonthOffset] = useState(0);
  const [selectedId, setSelectedId] = useState(null);

  if (!today) return null; // the calendar depends on today's date, known only in the browser
  const month = new Date(today.getFullYear(), today.getMonth() + monthOffset, 1);
  const weekEnd = toISODate(addDays(today, 6 - today.getDay()));
  const next = upcoming(posts, today);
  const thisWeek = next.filter((p) => p.date <= weekEnd);
  const prefix = toISODate(month).slice(0, 7);
  const visible = posts.filter((p) => (channel === "All" || p.channel === channel) && p.date.startsWith(prefix)).sort(byDateTime);
  const selected = posts.find((p) => p.id === selectedId);
  const shift = (n) => setMonthOffset((o) => o + n);

  return (
    <div className="w-full">
      <PageTitle eyebrow="AI content planner" title="Your content calendar" description="Create a complete posting plan in two simple steps.">
        <button type="button" onClick={onCreate} className={primary}>
          <Icon name="sparkles" size={14} /> Create a plan
        </button>
      </PageTitle>

      {added > 0 && (
        <div role="status" className="mb-[18px] flex items-center gap-3 rounded-[18px] bg-sense-lime p-4 text-sense-navy">
          <Icon name="calendar" size={20} />
          <p className="flex-1 text-xs">
            <strong className="block">{added} posts added to your calendar</strong>
            Click a post to see its caption or start writing it.
          </p>
          <button type="button" onClick={onDismiss} className="cursor-pointer rounded-full px-3 py-1.5 text-[11px] font-bold hover:bg-sense-navy/10">
            Dismiss
          </button>
        </div>
      )}

      <section className="mb-[18px] grid gap-[18px] md:grid-cols-3">
        <StatusCard
          icon="calendar"
          label="This week"
          value={`${thisWeek.length} post${thisWeek.length === 1 ? "" : "s"} planned`}
          note={next[0] ? `Next: ${next[0].channel} · ${fmtDay(next[0].date)} at ${next[0].time}` : "Nothing scheduled yet"}
        />
        <StatusCard icon="sparkles" label="AI recommendation" value={note ? "From your last plan" : "No plan yet"} note={note || "Create a plan to get posting advice."} />
        <StatusCard icon="content" label="Upcoming drafts" value={`${next.length} in total`} note="Nothing publishes automatically." />
      </section>

      <Panel>
        <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <button type="button" onClick={() => shift(-1)} aria-label="Previous month" className="grid size-8 cursor-pointer place-items-center rounded-full text-sense-blue hover:bg-sense-blue/10">
              <Icon name="chevron" size={16} className="rotate-180" />
            </button>
            <h3 className="min-w-[140px] text-center text-[17px] font-bold text-sense-blue">
              {month.toLocaleDateString("en-US", { month: "long", year: "numeric" })}
            </h3>
            <button type="button" onClick={() => shift(1)} aria-label="Next month" className="grid size-8 cursor-pointer place-items-center rounded-full text-sense-blue hover:bg-sense-blue/10">
              <Icon name="chevron" size={16} />
            </button>
          </div>
          <div role="group" aria-label="Filter by channel" className="flex flex-wrap gap-1.5">
            {["All", ...CHANNELS].map((c) => (
              <button
                key={c}
                type="button"
                aria-pressed={channel === c}
                onClick={() => setChannel(c)}
                className={`min-h-8 cursor-pointer rounded-2xl px-3.5 text-[11px] font-bold transition ${
                  channel === c ? "bg-sense-blue text-paper" : "bg-white/70 text-sense-blue hover:bg-sense-blue/10"
                }`}
              >
                {c}
              </button>
            ))}
          </div>
        </div>
        <MonthCalendar posts={visible} month={month} today={today} onSelect={setSelectedId} selectedId={selectedId} />
        <AgendaList posts={visible} onSelect={setSelectedId} selectedId={selectedId} />
        {!posts.length && (
          <p className="mt-4 text-center text-xs text-[#5f706e]">
            Your calendar is empty. Press <strong>Create a plan</strong> and Sense AI will fill it in.
          </p>
        )}
      </Panel>

      {selected && (
        <PostDetail
          post={selected}
          onClose={() => setSelectedId(null)}
          onRemove={() => {
            removePost(selected.id);
            setSelectedId(null);
          }}
        />
      )}
    </div>
  );
}

/* ---------- Page ---------- */

export default function AIManagementPage() {
  const { addPosts } = useCalendar();
  const [, setNote] = useStored(NOTE_KEY, NO_NOTE);
  const business = useBusiness();
  const [view, setView] = useState("dashboard");
  const [form, setForm] = useState({ goal: "", channels: ["Instagram", "TikTok"], perWeek: 3 });
  const [plan, setPlan] = useState(null);
  const [selected, setSelected] = useState([]);
  const [error, setError] = useState(null);
  const [added, setAdded] = useState(0);
  const [pending, startTransition] = useTransition();

  const submit = () => {
    setError(null);
    if (form.goal.trim().length < 5) return setError("Describe what your content should achieve.");
    if (!form.channels.length) return setError("Choose at least one channel.");
    const start = addDays(new Date(), 1); // plans start tomorrow
    startTransition(async () => {
      const res = await createPostingPlan({ ...form, startWeekday: WEEKDAYS[start.getDay()], business });
      if (res.error) return setError(res.error);
      const posts = res.plan.posts.map(({ dayOffset, ...p }) => ({ ...p, date: toISODate(addDays(start, dayOffset)) }));
      setPlan({ recommendation: res.plan.recommendation, posts });
      setSelected(posts.map((_, i) => i));
      setView("review");
    });
  };

  const addToCalendar = () => {
    const chosen = plan.posts.filter((_, i) => selected.includes(i));
    addPosts(chosen);
    if (plan.recommendation) setNote(plan.recommendation);
    setAdded(chosen.length);
    setPlan(null);
    setView("dashboard");
  };

  if (view === "plan")
    return <PlanForm form={form} setForm={setForm} onSubmit={submit} pending={pending} error={error} onBack={() => setView("dashboard")} />;
  if (view === "review" && plan)
    return <Review plan={plan} form={form} selected={selected} setSelected={setSelected} onBack={() => setView("plan")} onAdd={addToCalendar} />;
  return <Dashboard onCreate={() => setView("plan")} added={added} onDismiss={() => setAdded(0)} />;
}
